-- 2258 🏋️ Exercises from the book "marcelo-bielsa-coaching-build-up-play-against-high-pressing-teams" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'marcelo-bielsa-coaching-build-up-play-against-high-pressing-teams');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Read the winger: build up through centre', 'passing_opposed', 'overload', 'in_possession', 35, 36, 'Session 1: Practice 1', 'Marcelo Bielsa (Marseille / Athletic Bilbao)', 'Building out through the centre midfielder and choosing the right forward pass depending on what the opposition winger does.', 'Two thirds of a pitch with a marked central box, a yellow zone on each flank, two blue mannequins as central midfielders inside the box and three mini goals on the far line. Seven whites plus GK start on white cones in a 1-3-3 shape, two blue wingers on blue cones.', 'Coach plays long to the GK, who finds the dropping No.6; he carries forward and reads the blue winger. If the winger stays wide, No.6 threads a pass between winger and mannequin for No.7 to turn and score in a mini goal or lay off first time to No.10; if the winger tucks inside, No.6 lofts the ball over to the overlapping wing back in the yellow zone, who passes into a mini goal.', 'Midfielders must receive, turn and pass inside the central box; the long ball to the wing back must be played into and received inside the yellow side zone.', 'Leads into Practice 2 (live full backs and midfielders replace the mannequins).', 'Read the picture fast and pick the correct option; synchronised movement, clean receiving and turning, combination play in tight space, accurate passing.', '7 + GK v 2', 10, 10, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Build up through centre functional practice', 'phase_of_play', 'overload', 'in_possession', 37, 37, 'Session 1: Practice 2', 'Marcelo Bielsa (Marseille / Athletic Bilbao)', 'Building up from the GK through the centre against live midfield and full-back pressure, reading how the wingers and full backs react.', 'Same two-thirds pitch, central box, yellow flank zones and three mini goals as Practice 1, but the mannequins are replaced by two blue central midfielders and two blue full backs are added alongside the two blue wingers. A white line and a red line are marked for blue counters.', 'Coach serves to the GK, No.6 drops to receive and the whites work the ball forward choosing between the through pass when wingers stay wide, the aerial ball behind a full back who steps up, the switch to the wing back when wingers tuck in, or a first-time inside pass to No.10 via a link player when full back and winger cover the flank. Whites finish in the mini goals; if blues win it they try to dribble over the white line (1 point) or red line (3 points) within 8-10 seconds.', 'Same as Practice 1, except a long ball from No.6 behind a blue full back who has stepped up may be received outside the yellow zone. Blue counter must be completed in 8-10 seconds.', 'Progresses to Practice 3 (11v11 zonal game).', 'Recognise which of the four defensive reactions is happening and play the matching pass; link players offer angles; quick, accurate passing.', '7 + GK v 6', 14, 14, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Build up through centre zonal game', 'conditioned_game', 'opposed', 'in_possession', 38, 38, 'Session 1: Practice 3', 'Marcelo Bielsa (Marseille / Athletic Bilbao)', 'Applying the centre build-up decisions in a full 11v11 game against a 4-4-2 that tries to win the ball and counter.', 'Pitch split into five zones (central box, two side zones and an end zone in front of a full goal with GK). Whites start in 4-2-3-1 and shift to Bielsa''s 3-3-3-1; blues defend in 4-4-2.', 'Coach passes to the white GK, who plays No.6 in the centre; whites read the situation, build up through the centre and try to score past the GK in the big goal. Blues press to win it and then counter, scoring within 8-10 seconds by dribbling across the white line (1 point) or red line (3 points).', 'Blues may not enter the yellow zone when defending. Central-box restrictions are dropped, but the box stays marked to help whites read where space is (e.g. a winger stepping in frees the flank for the full back).', NULL, 'Make the correct decision from the earlier practices under real pressure.', '11 v 11', 22, 22, 'full pitch divided into 5 zones', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Build-up pattern switching play vs 2 forwards', 'passing_unopposed', 'unopposed', 'in_possession', 46, 46, 'Session 2: Practice 1', 'Marcelo Bielsa', 'Rehearse playing through the strong side and switching the play when building up against two forwards.', 'Half pitch plus about 10 yards with a full goal and GK; two wide boxes marked near the halfway line and two small goals on the far line. Whites in a 2-1-2 shape: two centre backs, one central midfielder, two wingers on the halfway line (5 to 10 outfield players, doubled up per position).', 'One centre back plays to the GK, who finds the other centre back stepping out; he plays forward to the winger, who frees himself and lays off first time to the central midfielder. The midfielder hits a long switch into the wide box for the far centre back who has pushed up, and he dribbles on and scores in the small goal. Repeat starting from the other side.', NULL, NULL, 'Sync timing and arrive at the ball moving; central midfielder''s long passes must land inside the wide boxes.', '5-10 outfield + GK', 6, 11, 'half pitch + 10 yards', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('8+GK v 6 strong side build-up and switch', 'phase_of_play', 'opposed', 'in_possession', 47, 47, 'Session 2: Practice 2', 'Marcelo Bielsa', 'Play through pressure on the strong side and switch the play against a 4-2 shape with two forwards.', 'Area from the halfway line to the penalty box (two thirds of a pitch); full goal with GK at one end, two small goals at the other. Whites (8 + GK) in a 3-3-2 from Bielsa''s 3-3-3-1; blues (6) in a 4-2 with two forwards.', 'Coach plays long to the GK while whites move off their cones into shape; GK plays to a centre back. Nearest blue forward presses to stop a 3v2 and the blues shift to the ball side to win it; whites use the link player to work the ball across and attack the 2v1 or 3v2 on the far side and score in a small goal. Blues who win it try to score within 8-10 seconds.', 'Blue weak-side winger shifts across but must stay on the weak side.', NULL, 'Read the situation and make the right movements and passes to switch.', '8+GK v 6', 15, 15, 'two thirds of a pitch (halfway line to penalty area)', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Switch vs 2 forwards then weak-side combinations', 'combination', 'unopposed', 'in_possession', 49, 50, 'Session 3: Practice 1', 'Marcelo Bielsa', 'Rehearse the four ways to switch play against two forwards and then finish with a combination on the weak side.', 'Half pitch plus 15 yards with full goals and GKs at both ends; 8 mannequins as opponents and 4 wide boxes. Back four, three midfielders and a forward.', 'Coach feeds the GK, who passes to a centre back opening up; the switch goes via the GK, directly to the central midfielder, via the winger as link player, or via the full back as link player back to the GK. Depending on which wide box receives the switch, the side runs one of three patterns (centre back carries and finds the full back while winger runs in behind; full back 1-2 with winger to get behind; winger overlap) and finishes past the GK with the forward timing his run.', 'Switch done within 6-8 seconds of the GK''s first pass; weak-side combination finished within 6-8 seconds of the long pass.', NULL, 'Synchronised timing and movement onto the ball; accurate long passes from the central midfielder; everything at speed.', '8 outfield + 2 GKs', 10, 10, 'half pitch + 15 yards', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('9v4 functional switch and weak-side 3v2', 'phase_of_play', 'overload', 'in_possession', 51, 52, 'Session 3: Practice 2', 'Marcelo Bielsa', 'Play through pressure, switch to the weak side and attack a 3v2 or 2v1 near the touchline.', 'Two thirds of a pitch with full goals and GKs at each end; 4 blue mannequins, two side zones and an end zone. Whites 9 outfield, blues 4.', 'Coach feeds the GK, who moves to one side and finds a centre back; the ball goes into a side zone and the whites switch using the previous practice''s options. Far centre back receiving gives a 3v2, full back receiving a 2v1; whites dribble over the red line or receive beyond it in the end zone and finish with support from the 9 and 10 (winger diagonal run, full back 1-2 overlap, or winger overlap).', '6-8 seconds to use the overload once the switch arrives; blues cannot defend inside the end zone.', NULL, 'Read the situation and pick the right combination; exploit the overload quickly.', '9 v 4 + 2 GKs', 15, 15, 'two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('9v8 functional game, switch vs 2 forwards', 'conditioned_game', 'opposed', 'in_possession', 53, 53, 'Session 3: Practice 3', 'Marcelo Bielsa', 'Choose between attacking the strong side or switching to exploit the weak side against two pressing forwards.', 'Pitch with 18-yard end zones and full goals with GKs; side boxes marked; 9 white and 8 blue outfield players starting on cones.', 'Coach feeds the GK, who passes to a centre back in a side box, creating a 4v4 as the blue forward and teammates shift over. Whites attack the strong side by dribbling into or receiving in the end zone if the blues are disorganised, otherwise switch with the earlier options and run the weak-side combinations to score; blues who win it counter within 8-10 seconds. Play both sides.', 'Blues may not defend on the weak side or inside the end zone.', NULL, 'Read the situation and pick the right way to switch; execute at speed.', '9 v 8 + 2 GKs', 19, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('11v11 zonal game, switch vs 2 forwards', 'conditioned_game', 'opposed', 'in_possession', 54, 54, 'Session 3: Practice 4', 'Marcelo Bielsa', 'Beat pressure on the strong side and use the numerical edge on the weak side after a switch.', 'Full pitch split into 5 zones: two 18-yard end zones and a middle third cut into three vertical channels. Whites in Bielsa''s 3-3-3-1 when building, blues with two forwards.', 'After the GK receives, whites shape up and the centre back gets it; blues shift to the strong side. Whites attack there if the blues are disorganised, otherwise switch to the far third; once there they have 6-8 seconds to use the 3v2 or 2v1 and dribble over the red line or receive beyond it and score. Blues winning it counter within 8-10 seconds.', 'Blue weak-side winger and full back must shift into the central zone when pressing; blues cannot defend in the end zone.', NULL, NULL, '11 v 11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Build-up pattern switching play vs 1 forward', 'passing_unopposed', 'unopposed', 'in_possession', 64, 64, 'Session 4: Practice 1', 'Marcelo Bielsa', 'Rehearse playing through the strong side and switching against a single forward.', 'Half pitch plus about 10 yards, full goal with GK, two wide boxes near halfway and two small goals on the far line. Whites in a 2-2-2: two centre backs, two central midfielders (one drops in) and two wingers on the halfway line; 6-12 outfield players.', 'Left centre back plays to the GK, who finds the right centre back; the 6 drops to balance. Right centre back can play to the winger or the other midfielder, who returns it to the dropped 6; the 6 switches long into the far wide box for the far centre back, who has pushed on, to score in a small goal. Repeat from the other side.', NULL, NULL, 'Sync timing and arrive moving; long passes must land inside the wide boxes.', '6-12 outfield + GK', 7, 13, 'half pitch + 10 yards', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('8+GK v 6 switch vs 1 forward', 'phase_of_play', 'opposed', 'in_possession', 65, 65, 'Session 4: Practice 2', 'Marcelo Bielsa', 'Work the ball out of strong-side pressure and switch when facing a 2-3-1 with one forward.', 'Halfway line to penalty box (two thirds of a pitch); full goal and GK at one end, two small goals at the other. Whites start in a 4-2-2 and become a 3-3-2 as the 6 drops; blues in a 2-3-1.', 'Coach plays long to the GK as whites move into shape; GK finds a centre back. Blue forward presses to block a 3v2 and the rest shift to the ball; whites switch to the 2v1 on the far side by going back to the GK, forward to the winger who returns to the GK, or inside to the 8 who returns to the GK (or via the 6 if open) and score in a small goal. Blues who win it score within 8-10 seconds.', NULL, NULL, NULL, '8+GK v 6', 15, 15, 'two thirds of a pitch (halfway line to penalty area)', NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Switch vs 1 forward then weak-side combinations', 'combination', 'unopposed', 'in_possession', 67, 68, 'Session 5: Practice 1', 'Marcelo Bielsa', 'Rehearse the four switching routes against one forward and finish with a weak-side combination.', 'Same as the two-forward version: half pitch plus 15 yards, full goals and GKs both ends, 8 mannequins and 4 wide boxes, with one extra white central midfielder.', 'Coach feeds the GK, who goes to a centre back; he switches via the GK if open, via the winger dropping as link player, via the central midfielder as link player, or via the full back dropping back to the GK. Depending on where the switch lands the team runs a pattern (centre back carries and finds the full back with winger running behind; full back 1-2 with winger; winger overlap) and the forward times his run to finish past the GK.', 'Switch done within 6-8 seconds of the GK''s first pass; combination finished within 6-8 seconds of the long pass.', NULL, 'Synchronised timing and movement onto the ball; accurate long passes; everything at speed.', '9 outfield + 2 GKs', 11, 11, 'half pitch + 15 yards', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('10v4 functional switch vs 1 forward', 'phase_of_play', 'overload', 'in_possession', 69, 70, 'Session 5: Practice 2', 'Marcelo Bielsa', 'Switch the play against one forward and attack a 3v2 or 2v1 in the far side zone.', 'Two thirds of a pitch, full goals and GKs both ends; 4 blue mannequins, two side zones and an end zone. Whites 10 outfield, blues 4.', 'Coach feeds the GK, who moves to one side and finds a centre back; ball goes into a side zone and whites switch using the earlier options. Far centre back receiving gives a 3v2, full back a 2v1; whites get over the red line by dribble or pass into the end zone using a winger diagonal run or a full back 1-2 and overlap, then score.', '6-8 seconds to use the overload once the switch arrives; blues cannot defend inside the end zone.', NULL, 'Read the situation and pick the right combination; be quick and efficient.', '10 v 4 + 2 GKs', 16, 16, 'two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('10v8 functional game, switch vs 1 forward', 'conditioned_game', 'opposed', 'in_possession', 71, 71, 'Session 5: Practice 3', 'Marcelo Bielsa', 'Decide between attacking the strong side and switching to the weak side against one forward plus a shifting 10.', '18-yard end zones with full goals and GKs; side boxes; 10 white and 8 blue outfield players starting on cones.', 'Coach feeds the GK, who must pass to the side the blue 9 is on; a centre back in the side box faces a 4v5 as blue 9 and 10 shift across. Whites attack the strong side into the end zone if the blues are disorganised, otherwise switch with the earlier options and use the weak-side combinations to score; blues who win it counter within 8-10 seconds. Both sides.', 'GK plays to the blue 9''s side (blue 10 starts central); blues may not defend on the weak side or in the end zone.', NULL, NULL, '10 v 8 + 2 GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 140),
  ('11v11 zonal game, switch vs 1 forward', 'conditioned_game', 'opposed', 'in_possession', 72, 72, 'Session 5: Practice 4', 'Marcelo Bielsa', 'Beat strong-side pressure from a one-forward team and use the weak-side overload after the switch.', 'Full pitch in 5 zones: two 18-yard end zones and a middle third in three vertical channels. 11 v 11.', 'GK receives, whites take shape and a centre back gets it while the weak-side central midfielder drops to help switch and cover. Blues shift to the strong side; whites switch to the far third and then have 6-8 seconds to use the 3v2 or 2v1, dribbling over or receiving beyond the red line and scoring. Blues who win it counter within 8-10 seconds.', 'GK plays to blue 9''s side (blue 10 central); blue weak-side winger and full back shift into the central zone when pressing; blues cannot defend in the end zone.', NULL, NULL, '11 v 11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Passing lanes around mannequins, double-ended circuit', 'passing_unopposed', 'unopposed', 'in_possession', 83, 83, 'Session 6: Practice 1', 'Marcelo Bielsa', 'Pass and receive at different angles, timing movement into open passing lanes.', '35 x 50 yard area with 12 mannequins, 4 cone gates and 10 red starting cones; 12 players, a ball at each end with start groups A1 and A2.', 'Both ends start together. A1 plays to C, who drops and sets into the path of B dribbling through a gate; B passes forward to D who has dropped into a lane, while C curls round the mannequins to take D''s pass and play to the opposite start. Rotate A to B to C to D to start.', NULL, NULL, 'Move into the lane to receive forward passes at the right moment; time the run round the mannequins to take the lay-off moving.', '12 players', 12, 12, '35 x 50 yards', 45.7, 32.0, NULL, false, false, true, NULL, 160),
  ('Full back and winger combinations circuit', 'passing_unopposed', 'unopposed', 'in_possession', 84, 84, 'Session 6: Practice 2', 'Marcelo Bielsa', 'Rehearse synchronised full back and winger movements and combinations near the touchline.', 'Same type of area with mannequins and cones repositioned plus two small boxes (4 x 6 and 5 x 8 yards); start groups at each end.', 'Right side: A1 one-two with B dropping, then dribbles and passes into the small box where winger D has dropped to receive and turn; full back C runs forward wide, gets the ball and passes to D who runs inside the mannequin and plays to the far start. Left side: A2 one-two with B, dribbles and plays an aerial ball into the bigger box for C who has pushed forward; C finishes by passing to the A1 start. Rotate A to B to C to D.', NULL, 'Run it mirrored for the other flank; D can play first time to C and spin behind the mannequin instead of turning.', NULL, '12 players', 12, 12, '35 x 50 yards (implied, as previous)', NULL, NULL, NULL, false, false, true, NULL, 170),
  ('Full back and winger combos vs live full back', 'passing_opposed', 'opposed', 'in_possession', 85, 85, 'Session 6: Practice 3', 'Bielsa', 'Read a defending full back''s reaction and choose the right full back / winger combination to get a 2v1 near the touchline.', '35 x 50 yard area with a 4-5 yard central channel; two 10 x 15 yard marked zones each holding a white winger and a blue full back; groups of starters at both ends.', 'A1 and A2 start at opposite ends, play a one-two with a midfielder, receive back, dribble forward and pick a pass while the winger drops to offer an option. If the full back stays, the winger turns into a 2v1; if he follows, the full back gets a ball over the top into the zone; if he waits then presses, the winger lays it first time into the full back''s run.', 'Each combination finishes with a pass to the starter at the far end.', 'Run it reversed to train the left side.', 'Decision follows the defender''s reaction.', NULL, NULL, NULL, '35 x 50 yards', 45.7, 32.0, NULL, false, false, true, NULL, 180),
  ('3v1 near touchline find free player', 'one_v_one', 'opposed', 'in_possession', 86, 86, 'Session 6: Practice 4', 'Bielsa', 'Exploit a 3v1 near the sideline by getting the ball to the free full back.', 'Two 20 x 60 yard areas, each split into halves with a small goal at the end; each group has a centre back, full back and winger plus one blue defender; an extra white player waits outside.', 'The centre back dribbles forward as the defender steps up; he passes straight to the full back if the lane is open, or via the winger dropping as a link player if not. The full back then dribbles into the attacking half and shoots.', 'Only the full back may carry the ball into the attacking half; both groups work in opposite directions at once.', 'Reverse for the left side.', 'Read the defender''s position to pick direct pass or link pass.', '3v1 per group, 2 groups of 5', 10, 10, '20 x 60 yards (x2)', 54.8, 18.3, NULL, true, false, true, NULL, 190),
  ('3v2 near touchline find free player', 'one_v_one', 'opposed', 'in_possession', 87, 87, 'Session 6: Practice 5', 'Bielsa', 'Use the numerical edge of a 3v2 near the sideline to get the full back in behind.', 'Same two 20 x 60 yard areas as the 3v1, now with two blue defenders per group; an outside player serves into the centre back.', 'The outside player passes to the centre back who enters. If one defender presses him and the other tracks the dropping winger, the full back gets the ball and runs on to score; if the full back is left open, it is an instant 2v1 and the winger curls a run in behind for a through pass.', 'Only the full back may enter the attacking half with the ball.', 'Reverse for the left side.', 'React to the two defenders and pick the right combination.', '3v2 per group', 10, 12, '20 x 60 yards (x2)', 54.8, 18.3, NULL, true, false, true, NULL, 200),
  ('3v2 side-zone functional build-up', 'phase_of_play', 'opposed', 'in_possession', 88, 88, 'Session 6: Practice 6', 'Bielsa', 'Build up from the goalkeeper against two forwards and exploit a 3v2 in a wide zone.', 'Two thirds of a pitch with a side zone on each flank holding a full back and winger from both teams, each zone with an end zone and small goal; two white centre backs and two central midfielders in the middle, GK in the full goal.', 'Coach plays long to the keeper; whites shape up 3-3-2 (from 3-3-3-1) with centre backs splitting wide and the 6 dropping in. When a centre back receives he steps into the side zone and the whites must dribble over the red line or pass into the end zone and score within 8 seconds.', 'Blues cannot defend behind the red line; offside applies. Blues winning it counter by dribbling through the far red line or passing beyond it within 5 seconds; white 8 may enter side zones in negative transition.', NULL, NULL, NULL, NULL, NULL, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('3v2 wide overload 11v10 game', 'conditioned_game', 'opposed', 'in_possession', 89, 89, 'Session 6: Practice 7', 'Bielsa', 'Create and exploit a 3v2 near the sideline within a full team game.', 'Same layout as the functional practice but the end zone spans the full width (15 yards deep) with 3 small goals.', 'Coach plays long to the keeper and whites shape to build against 2 forwards. Normal game, but when a white centre back enters a side zone the whites aim to dribble over the red line or pass beyond it and score within 5-6 seconds; such a goal counts double.', 'Blue forwards don''t stop centre backs entering the zones. Blues win it and score within 8-10 seconds; no defending in the end zone; offside applies.', NULL, 'Whites choose the solution based on the blues'' reaction.', '11v10', 21, 21, '2/3 pitch, end zone 15 yards', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('3v2 wide overload 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 90, 90, 'Session 6: Practice 8', 'Bielsa', 'Exploit a 3v2 out wide and finish with crosses into a big goal.', 'As the 11v10 game but the end zone is 25 yards deep and there is a full-size goal with a goalkeeper.', 'Whites still look for the wide 3v2 but now aim to cross and finish in the large goal; blues defend and counter against the other keeper.', 'Same rules and restrictions as the previous practice.', NULL, NULL, '11v11', 22, 22, '2/3 pitch, end zone 25 yards', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Switch to full backs passing circuit', 'passing_unopposed', 'unopposed', 'in_possession', 98, 98, 'Session 7: Practice 1', 'Bielsa', 'Rehearse the quick lay-off and switch of play to a full back in space.', '60 x 60 yard area, 12 players, 2 mannequins, 4 cone gates; groups of centre back and two midfielders at each end, full backs (2 per end) either side of an 8 x 8 yard box.', 'A passes to C who lays back; A dribbles through a gate and plays to B dropping; B gives inside to C who switches long into the 8 x 8 box for a full back, who receives, dribbles on, plays a one-two with the second full back and passes to E. The same pattern runs with E, F, G switching back the other way.', NULL, 'Full backs swap sides each time they receive; others rotate A to B to C to start.', 'C and G time their movement to receive the lay-off and switch first time.', '12', 12, 12, '60 x 60 yards', 54.8, 54.8, NULL, false, false, false, NULL, 240),
  ('Beat 3v3 near sideline zonal game (2 forwards)', 'phase_of_play', 'opposed', 'in_possession', 99, 99, 'Session 7: Practice 2', 'Bielsa', 'Read whether the opposition blocks the wide 3v2 and either use it or switch / play through when they make it 3v3.', 'Two thirds of a pitch split into 6 zones; full goal and keeper at one end, 3 small goals at the other.', 'Coach plays long to the keeper; whites set up 3-3-1 style against 2 forwards with centre backs wide and the 6 dropping. When a centre back gets the ball, blues allow a 3v2 or shift their midfielder to make 3v3; whites exploit the 3v2 or switch to the weak side or thread a pass to 7, 10 or 11, then dribble over or pass beyond the red line and shoot in a small goal.', 'Blues cannot defend in the end zone; blue forwards stay in their zone when defending. Blues winning it wide dribble through the red line; winning centrally they score past the keeper within 8-10 seconds.', NULL, NULL, NULL, NULL, NULL, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Beat 3v3 near sideline zonal game (1 forward)', 'phase_of_play', 'opposed', 'in_possession', 100, 100, 'Session 7: Practice 3', 'Bielsa', 'Solve the wide 3v3 against a one-forward team by switching play or a through pass.', 'Same zonal layout as the previous practice.', 'Same aims and rules, but against one forward the first midfielder does not drop (2v1 at the back). When the side zone becomes 3v3, the 8 either switches long to the far full back if the midfield is compact, or plays through a gap to the 10 if the blue winger stays wide.', 'As previous practice.', NULL, 'Midfielder picks switch or through pass; play quickly after it to exploit the overload.', NULL, NULL, NULL, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Beat 3v3 near sideline 11v11 zonal game', 'conditioned_game', 'opposed', 'in_possession', 101, 101, 'Session 7: Practice 4', 'Bielsa', 'Apply the 3v2 / 3v3 wide solutions in a full 11v11.', 'Same zones, now with two full-size goals and keepers.', 'Whites use their back numbers to create a 3v2 in a side zone; if blues make it 3v3, the free 8 is found via a link player and switches or plays in behind for a run and cross to finish. Blues defend and try to score within 8-10 seconds.', 'Blues cannot defend in the end zone; blue forwards stay in their zone when defending.', NULL, NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('One-two then long pass into box', 'passing_unopposed', 'unopposed', 'in_possession', 106, 106, 'Session 8: Practice 1', 'Bielsa', 'Practise a long pass and a timed run to receive it in a small target area.', '40 x 60 yard area split down the middle, 12 players, 2 mannequins, red start cones and a 10 x 8 yard target box at opposite ends.', 'Two balls, both sides at once: A plays a one-two around the mannequin with B dropping; C drops to open space behind and D runs into the target box; A hits a long pass for D to receive inside the box, who then passes to A on the other side.', NULL, 'Reverse for the left side; change the box size for age/level.', NULL, '12', 12, 12, '40 x 60 yards', 54.8, 36.6, NULL, false, false, false, NULL, 280),
  ('4v3 or 4v4 dynamic zonal practice', 'phase_of_play', 'opposed', 'in_possession', 107, 108, 'Session 8: Practice 2', 'Bielsa', 'Centre back reads the defenders'' reaction to exploit a 4v3 or solve a 4v4 around the ball.', '55 x 60 yard area in 6 zones: four 25 x 30 zones and two 5 x 30 middle channels, small red side zones for switches, two goals with keepers diagonally opposite. Whites per half: CB, FB, CM and FW1, with FW2 in the middle channel; blues have W and CM in one half, FB and CB in the other.', 'Both sides run at once from a coach pass to the white CB. If both blue defenders squeeze FW1 and FB (4v4), a long ball goes over for FW2 to score; if the blue winger presses, FW1 drops for 4v3 and the free FB attacks a 3v2/2v1; if the winger holds wide, the free CM receives and switches to the far full back.', 'One white may move up from the first half to join the two forwards; only blue CB and FB can cross halves; side zone players swap regularly.', 'Players rotate or keep positions; FW1 and FW2 may swap; reverse for left side.', 'CB reads the situation; the opposing winger''s reaction drives the decision.', NULL, NULL, NULL, '55 x 60 yards', 54.8, 50.3, NULL, true, true, true, NULL, 290),
  ('4v3 or 4v4 near sideline zonal game', 'phase_of_play', 'opposed', 'in_possession', 109, 110, 'Session 8: Practice 3', 'Bielsa', 'Create and use a 4v3 near the sideline, or a long pass in behind when it becomes 4v4.', 'Two thirds of a pitch in 3 zones; full goal with keeper at one end, 3 small goals at the other, end zone 25 yards x full width.', 'Coach plays long to the keeper; whites take a 3-4-3 shape against 2 forwards. The receiving centre back steps into the side zone: if the blue winger presses, find the free full back via link player 10; if the blue centre back follows the 10 (4v4), hit the runner 9 in behind; if the blue 8 presses, 7 is free to switch to the weak side. Score by dribbling over the red line or receiving in the end zone onside.', 'Only the near blue winger, full back, CM and CB may enter the side zone; blues cannot defend beyond the red line. Blues winning it in the zone counter over the red line and score within 8-10 seconds.', NULL, 'Defender in possession reads the reaction; winger''s reaction is key.', NULL, NULL, NULL, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('4v3 or 4v4 near sideline 11v11', 'conditioned_game', 'opposed', 'in_possession', 111, 111, 'Session 8: Practice 4', 'Bielsa', 'Apply the 4v3/4v4 wide solutions in a full game, finishing in a big goal.', 'As the zonal game but the whites attack a full-size goal with a keeper.', 'Same aims and rules; with a full goal the whites will pass or cross from wide to score, e.g. free 7 switching long to the left back.', 'Same restrictions as the previous practice.', NULL, NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Link player combos to get in behind', 'combination', 'unopposed', 'in_possession', 118, 118, 'Session 9: Practice 1', 'Bielsa', 'Move the ball past a pressing opponent two ways: via a link player and via a long pass.', '30 x 50 yard area split in two halves, each with 2 mannequins and a small goal; the left side has a receiving box for H.', 'Right: A to B, D drops into a lane as link player, C runs forward; B finds C via D, C dribbles, one-two with E and scores. Left: F one-two with G, I drops, H runs on to a long pass in the box, I curls behind the mannequin, H feeds I to score.', 'Players move one position on after each go.', NULL, 'Quick, synchronised combinations with accurate passing; aim is to reach the player behind the mannequin.', NULL, NULL, NULL, '30 x 50 yards', 45.7, 27.4, NULL, true, false, true, NULL, 320),
  ('Break ultra-high press one side 8v8', 'phase_of_play', 'opposed', 'in_possession', 119, 120, 'Session 9: Practice 2', 'Bielsa', 'Beat an ultra-offensive press on the strong side by finding the free full back.', 'Two thirds of a pitch with a white build-up zone and a yellow end zone; whites have a keeper in a full goal, blues defend 2 small goals; start positions coned.', 'Coach plays long to the keeper; 6 drops to make a back three, centre backs split, full backs push on. Blue forwards mark two of three at the back, one winger tracks the far full back, the other balances between centre back and full back and steps in when the keeper passes, creating 3v3. Whites get the ball to the free full back via link player 11, or back to the keeper for a long pass, then dribble into or receive in the yellow zone and score.', 'Only strong-side players take part (take turns each side); blues cannot enter the yellow zone. Blues winning it score past the keeper within 8-10 seconds.', NULL, 'Read the blue central midfielder: if central, use the link player; if he shifts, play back to the keeper.', '8(+GK) v 8', 17, 17, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('Break ultra-high press 11v11 zonal game', 'conditioned_game', 'opposed', 'in_possession', 121, 122, 'Session 9: Practice 3', 'Bielsa', 'Build up against ultra-offensive pressing and move the ball to the free full back behind an opponent.', 'Same area as the 8v8 but not split; all players involved with a full goal and keeper at the end.', 'Coach plays long to the keeper and whites form a back three against 2 forwards; a blue winger jumps on the centre back to make 3v3. Whites reach the free full back through a link player or a long keeper pass, then dribble into or receive in the yellow zone and finish past the keeper.', 'Same restrictions as previous practice; blues winning it score within 8-10 seconds.', NULL, 'Quick combinations and synchronised movement; read the blue 8 to choose link player or back to keeper.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 340)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'marcelo-bielsa-coaching-build-up-play-against-high-pressing-teams') b;
